from itertools import permutations
from collections import defaultdict

golfers = 30
weeks = 7
groups = 10

# Create a dictionary to store the groups for each week
schedule = defaultdict(list)

# Function to check if a pair of golfers has been in the same group before
def has_been_in_same_group(golfer1, golfer2, week):
    for w in range(week):
        for group in schedule[w]:
            if golfer1 in group and golfer2 in group:
                return True
    return False

# Try to schedule the golfers
for week in range(weeks):
    groups = {}
    for golfer in range(golfers):
        assigned = False
        for group in range(groups):
            if len(groups.get(group, [])) < 3 and not any(has_been_in_same_group(golfer, g, week) for g in groups.get(group, [])):
                groups[group] = groups.get(group, []) + [golfer]
                assigned = True
                break
        if not assigned:
            print("UNSATISFIABLE")
            break
    else:
        schedule[week] = list(groups.values())
        continue
    break
